import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.7nMnW4XS.js";const p=JSON.parse('{"title":"/fly Cinematic Gap Analysis — Current State vs Shot-Language Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guides/fly-cinematic-gap-analysis.md","filePath":"guides/fly-cinematic-gap-analysis.md"}'),o={name:"guides/fly-cinematic-gap-analysis.md"};function s(n,t,d,l,h,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="fly-cinematic-gap-analysis-—-current-state-vs-shot-language-guide" tabindex="-1">/fly Cinematic Gap Analysis — Current State vs Shot-Language Guide <a class="header-anchor" href="#fly-cinematic-gap-analysis-—-current-state-vs-shot-language-guide" aria-label="Permalink to &quot;/fly Cinematic Gap Analysis — Current State vs Shot-Language Guide&quot;">​</a></h1><blockquote><p>Compiled 2026-06-10 after the Cassini hero-shot polish landed. Cross- references the standing shot-language doc (<a href="./fly-cinematic-shot-language">fly-cinematic-shot-language.md</a>) against the four lifecycle moments of a /fly mission: <strong>Start / Cruise / Flyby / Landing</strong>. Each row is a checklist principle; each column is where we are right now and what gets us to &quot;good enough to ship on YouTube next to a National Geographic flyby.&quot;</p><p>Quote the gaps as PR rationale in the next polish wave.</p></blockquote><hr><h2 id="lifecycle-moments" tabindex="-1">Lifecycle moments <a class="header-anchor" href="#lifecycle-moments" aria-label="Permalink to &quot;Lifecycle moments&quot;">​</a></h2><ol><li><strong>Start</strong> — mission load → camera converges on Earth → Launch (T+0)</li><li><strong>Cruise</strong> — post-Launch interplanetary coast</li><li><strong>Flyby</strong> — each cinema sub-phase (T−25d → T+25d around a planetary flyby)</li><li><strong>Landing / Arrival</strong> — final destination contact (Saturn OI for Cassini, the Mars descent for a lander mission, the lunar touchdown for Apollo)</li></ol><hr><h2 id="checklist-scorecard" tabindex="-1">Checklist scorecard <a class="header-anchor" href="#checklist-scorecard" aria-label="Permalink to &quot;Checklist scorecard&quot;">​</a></h2><h3 id="p1-space-is-dark-not-black" tabindex="-1">P1. Space is dark, not black <a class="header-anchor" href="#p1-space-is-dark-not-black" aria-label="Permalink to &quot;P1. Space is dark, not black&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Moment</th><th>State</th><th>Gap</th></tr></thead><tbody><tr><td>Start</td><td>Solid <code>#000</code> sky with sparse stars</td><td>Add cubemap skydome with Milky Way + ecliptic gradient</td></tr><tr><td>Cruise</td><td>Same</td><td>Same</td></tr><tr><td>Flyby</td><td>Same</td><td>Same — most critical here, the limb shot needs the bg gradient</td></tr><tr><td>Landing</td><td>Same</td><td>Same</td></tr></tbody></table><p><strong>Action:</strong> ship a baked TychoSkymap-style cubemap, lazy-promoted on first cinema frame. T8 in the guide.</p><hr><h3 id="p2-one-hard-light-one-soft-fill-nothing-else" tabindex="-1">P2. One hard light, one soft fill, nothing else <a class="header-anchor" href="#p2-one-hard-light-one-soft-fill-nothing-else" aria-label="Permalink to &quot;P2. One hard light, one soft fill, nothing else&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Moment</th><th>State</th><th>Gap</th></tr></thead><tbody><tr><td>Start</td><td><code>PointLight(0xfff4d0, 3.5, 2000, 1.2)</code> + <code>AmbientLight(0x111133, 0.8)</code></td><td><strong>Ambient light is the #1 anti-pattern.</strong> Replace with HemisphereLight at intensity 0.05–0.10</td></tr><tr><td>Cruise</td><td>Same</td><td>Same</td></tr><tr><td>Flyby</td><td>Same — no planet-bounce light on spacecraft</td><td>Add per-frame DirectionalLight aimed planet→spacecraft, intensity scaled by albedo/dist²</td></tr><tr><td>Landing</td><td>Same</td><td>Same</td></tr></tbody></table><p><strong>Action:</strong> rip out <code>AmbientLight</code>. Wire a planet-bounce DirectionalLight that tracks the active body. T5 in the guide.</p><hr><h3 id="p3-the-silhouette-test" tabindex="-1">P3. The silhouette test <a class="header-anchor" href="#p3-the-silhouette-test" aria-label="Permalink to &quot;P3. The silhouette test&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Moment</th><th>State</th><th>Gap</th></tr></thead><tbody><tr><td>Start</td><td>Earth + ship readable</td><td>✓ Mostly passes</td></tr><tr><td>Cruise</td><td>Ship + trajectory readable but planets not silhouetted</td><td>OK — cruise is informational, not heroic</td></tr><tr><td>Flyby</td><td>Cassini at 64×64: bus + dish recognizable on Jupiter; barely on Venus</td><td>Push model scale up slightly OR rim-light so silhouette reads at thumbnail</td></tr><tr><td>Landing</td><td>Saturn rings dominate; ship invisible at 64×64</td><td><strong>Needs limb-grazing recomposition</strong> (T3)</td></tr></tbody></table><p><strong>Action:</strong> rim-light shader pass (T6) is the highest-impact single fix for the silhouette test. Costs ~1 ShaderMaterial; gains a CG → mission- art jump.</p><hr><h3 id="p4-three-layers-of-depth" tabindex="-1">P4. Three layers of depth <a class="header-anchor" href="#p4-three-layers-of-depth" aria-label="Permalink to &quot;P4. Three layers of depth&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Moment</th><th>State</th><th>Gap</th></tr></thead><tbody><tr><td>Start</td><td>Earth + trajectory + stars (2 layers)</td><td>Add the Moon + Sun-as-bright-disc for 4 layers</td></tr><tr><td>Cruise</td><td>Sun + asteroid belt + trajectory tube + stars (3-4 layers)</td><td>✓ Cruise is already strong</td></tr><tr><td>Flyby</td><td>Ship + planet + (moons if lens on) + stars (3-4 layers)</td><td>✓ With moons-on, Jupiter passes; Venus/Mercury have no moons → add zodiacal dust or distant context planet</td></tr><tr><td>Landing</td><td>Ship + Saturn + rings + stars</td><td>✓ Passes — rings provide the midground anchor</td></tr></tbody></table><p><strong>Action:</strong> turn moons layer ON by default during flyby cinema for bodies that have them. For moonless flybys (Mercury, Venus), pull the Sun into frame at small angular size as a third-layer reference (P5).</p><hr><h3 id="p5-scale-by-reference-not-size" tabindex="-1">P5. Scale by reference, not size <a class="header-anchor" href="#p5-scale-by-reference-not-size" aria-label="Permalink to &quot;P5. Scale by reference, not size&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Moment</th><th>State</th><th>Gap</th></tr></thead><tbody><tr><td>Start</td><td>Earth fully framed</td><td>Crop Earth limb. Show only a quarter of Earth, ship in foreground hanging off North Pole</td></tr><tr><td>Cruise</td><td>Wide-angle solar system</td><td>✓ Cruise is correctly scaled — sees Sun, belt, planets in correct proportion</td></tr><tr><td>Flyby</td><td>Planet at ~40-45% frame width — body still fully containable</td><td><strong>Cinema is too contained.</strong> Let the limb exit frame top + bottom. Reframe to limb-grazing (T3)</td></tr><tr><td>Landing</td><td>Saturn + rings fully visible</td><td>Same — let rings exit top of frame; close to Saturn limb</td></tr></tbody></table><p><strong>Action:</strong> rewrite cinema-target lerp so the planet <em>centre</em> drifts off-frame and the <em>limb</em> sits on the rule-of-thirds line. Highest- impact rewrite. T3 in the guide.</p><hr><h3 id="p6-camera-disagrees-with-subject" tabindex="-1">P6. Camera disagrees with subject <a class="header-anchor" href="#p6-camera-disagrees-with-subject" aria-label="Permalink to &quot;P6. Camera disagrees with subject&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Moment</th><th>State</th><th>Gap</th></tr></thead><tbody><tr><td>Start</td><td>Camera holds while ship leaves Earth</td><td>✓ Disagree works</td></tr><tr><td>Cruise</td><td>Slow azimuthal drift + zoom breathing + tilt drift</td><td>✓ Three layered oscillations — strongest current cinematic moment</td></tr><tr><td>Flyby</td><td>Camera follows planet-center target with 35% ship bias; ship pushed toward camera</td><td>Camera and ship are too correlated. <strong>Add a parallax arc</strong> during the cinema peak — boomYaw sweeps 60–90° as the ship reaches closest approach</td></tr><tr><td>Landing</td><td>Camera lerps to Saturn closeup</td><td>Add departure-style slow pull-out after arrival; &quot;afterglow beat&quot;</td></tr></tbody></table><p><strong>Action:</strong> in the cinema sub-phase, add a <code>peakOrbitDeg</code> clip that sweeps camT by ~60° around the body during the T−5d → T+2d window. Simplest cinematic upgrade after light. T4 in the guide.</p><hr><h3 id="p7-logarithmic-time-around-events" tabindex="-1">P7. Logarithmic time around events <a class="header-anchor" href="#p7-logarithmic-time-around-events" aria-label="Permalink to &quot;P7. Logarithmic time around events&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Moment</th><th>State</th><th>Gap</th></tr></thead><tbody><tr><td>Start</td><td>3.5s launch dwell ✓</td><td>Could extend to a slow Earth orbit reveal before the launch dwell ends</td></tr><tr><td>Cruise</td><td>Standard sim-speed</td><td>OK as a base rate; cinematic stretching belongs to the event windows</td></tr><tr><td>Flyby</td><td>Symmetric 25 days before / 25 days after</td><td><strong>Anti-pattern.</strong> Replace with asymmetric Freytag (T4) — approach 20d, peak 7d, departure 25-40d, slowed via sim-speed override during peak</td></tr><tr><td>Landing</td><td>Sim freezes on arrival</td><td>Add 5-8s departure-style pull-out on arrival before freeze</td></tr></tbody></table><p><strong>Action:</strong> introduce a <code>cinemaSimSpeedMultiplier</code> per stage so the 3-stage flyby Freytag stretches the peak in screen-time without touching the underlying physics. Same multiplier on landing afterglow.</p><hr><h2 id="post-processing-readiness" tabindex="-1">Post-processing readiness <a class="header-anchor" href="#post-processing-readiness" aria-label="Permalink to &quot;Post-processing readiness&quot;">​</a></h2><p>We currently have <strong>no post stack</strong>. Single highest-impact addition.</p><table tabindex="0"><thead><tr><th>Pass</th><th>Impact</th><th>Cost</th><th>Priority</th></tr></thead><tbody><tr><td><code>ACESFilmicToneMapping</code></td><td>Massive — instantly cinematic</td><td>~0ms</td><td><strong>Land first</strong></td></tr><tr><td><code>UnrealBloomPass</code></td><td>Sun bloom + plume glow</td><td>~2ms</td><td>High</td></tr><tr><td><code>FilmPass</code> (grain)</td><td>&quot;It&#39;s film not WebGL&quot;</td><td>~0.5ms</td><td>High</td></tr><tr><td><code>VignettePass</code></td><td>Subtle eye-pull</td><td>~0.3ms</td><td>Medium</td></tr><tr><td><code>BokehPass</code> (DoF)</td><td>Telephoto compression</td><td>~2ms</td><td>Medium — drop on mobile</td></tr><tr><td><code>Lensflare</code></td><td>One subtle anamorphic streak</td><td>~0.2ms</td><td>Low — sparingly</td></tr></tbody></table><p><strong>Action:</strong> add <code>THREE.ACESFilmicToneMapping</code> to the renderer in the <em>next commit</em>. Zero risk, immediate visual upgrade across every shot.</p><hr><h2 id="lifecycle-specific-gaps-what-to-do-next" tabindex="-1">Lifecycle-specific gaps (what to do next) <a class="header-anchor" href="#lifecycle-specific-gaps-what-to-do-next" aria-label="Permalink to &quot;Lifecycle-specific gaps (what to do next)&quot;">​</a></h2><h3 id="start-—-the-launch" tabindex="-1">Start — the launch <a class="header-anchor" href="#start-—-the-launch" aria-label="Permalink to &quot;Start — the launch&quot;">​</a></h3><ul><li>✓ Launch dwell holds MET 0 for 3.5s</li><li>✗ Composition is &quot;Earth fully in frame&quot; — should be Earth limb cropped, ship hanging off the pole</li><li>✗ No sense of acceleration — ship just departs at sim-speed. Need a brief telephoto compression + camera dolly that conveys <em>escape velocity</em></li><li>✗ No engine plume glow (T11) at the moment of departure — a 1-second orange burst against Earth&#39;s limb would sell the launch</li></ul><h3 id="cruise-—-the-long-coast" tabindex="-1">Cruise — the long coast <a class="header-anchor" href="#cruise-—-the-long-coast" aria-label="Permalink to &quot;Cruise — the long coast&quot;">​</a></h3><ul><li>✓ Layered camera oscillations (cruise drift + zoom breath + tilt drift) are the strongest current cinematic moment</li><li>✓ Asteroid belt + Kuiper belt visible at correct scales</li><li>✓ Diamonds-on-path + chip overlay system</li><li>✗ No engine-burn beats at TCM events (Trajectory Correction Manoeuvres)</li><li>✗ No mid-cruise &quot;scale beat&quot; — e.g., at the asteroid belt crossing, pause and let the ship drift through the dust field</li></ul><h3 id="flyby-—-the-hero-shot" tabindex="-1">Flyby — the hero shot <a class="header-anchor" href="#flyby-—-the-hero-shot" aria-label="Permalink to &quot;Flyby — the hero shot&quot;">​</a></h3><ul><li>✓ Ship in front of planet</li><li>✓ Per-body composition variation</li><li>✓ Boom orientation graceful</li><li>✓ Chip docks at bottom out of the hero area</li><li>✓ Anchor rings hidden at closeup</li><li>✗ <strong>Symmetric pacing</strong> (anti-pattern T4)</li><li>✗ <strong>Planet centred-and-contained</strong> vs limb-grazing (anti-pattern P5/T3)</li><li>✗ <strong>No rim-light</strong> on spacecraft (anti-pattern T6)</li><li>✗ <strong>No parallax disagree</strong> during peak (anti-pattern P6/T4-Peak)</li><li>✗ Stars + Sun background not richer (anti-pattern P1/T8)</li></ul><h3 id="landing-arrival" tabindex="-1">Landing / Arrival <a class="header-anchor" href="#landing-arrival" aria-label="Permalink to &quot;Landing / Arrival&quot;">​</a></h3><ul><li>✓ Saturn OI without ARRIVAL banner clutter (just shipped)</li><li>✗ Composition is &quot;Saturn fully framed with rings around&quot; not &quot;Cassini grazing Saturn&#39;s ring-plane edge&quot; (the actual mission-art reference)</li><li>✗ No &quot;afterglow&quot; beat — sim freezes immediately on arrival</li><li>✗ No engine plume glow during the 96-minute SOI burn</li><li>✗ No music or sound cue (out of scope for /fly but worth noting)</li></ul><hr><h2 id="prioritised-polish-wave-2-plan" tabindex="-1">Prioritised polish-wave-2 plan <a class="header-anchor" href="#prioritised-polish-wave-2-plan" aria-label="Permalink to &quot;Prioritised polish-wave-2 plan&quot;">​</a></h2><p>Ranked by impact-per-effort. Each item is roughly one commit.</p><ol><li><strong><code>ACESFilmicToneMapping</code> on renderer</strong> — zero effort, every shot improves. <em>(2 lines)</em></li><li><strong>Replace <code>AmbientLight</code> with <code>HemisphereLight(0.05)</code></strong> — restores shadow contrast. <em>(3 lines)</em></li><li><strong>Skydome cubemap</strong> with sparse stars + Milky Way + ecliptic gradient — kills the <code>#000</code> anti-pattern. <em>(1 asset + 10 lines)</em></li><li><strong>Rim-light Fresnel shader on scModel materials</strong> — the single biggest &quot;cinematic spacecraft&quot; upgrade. <em>(1 ShaderMaterial inject)</em></li><li><strong>Asymmetric Freytag pacing</strong> — 20d approach / 7d peak / 30d departure, with a sim-speed dilation during peak. <em>(30 lines refactor in updateHelioAutoZoomTargets)</em></li><li><strong>Limb-grazing target lerp</strong> — push planet centre off-frame so the limb arcs across rule-of-thirds. Highest visual jump after rim light. <em>(15 lines)</em></li><li><strong>Parallax orbit during peak</strong> — camT sweeps 60° during T−5d to T+2d window. Camera-disagree principle. <em>(10 lines)</em></li><li><strong><code>UnrealBloomPass</code> post stack</strong> — Sun bloom + plume glow when we add plumes. <em>(15 lines + EffectComposer wiring)</em></li><li><strong>Engine plume billboard at burn events</strong> — Earth-departure burst, Saturn-SOI 96-minute glow. <em>(20 lines + sprite asset)</em></li><li><strong>Saturn-OI limb-grazing composition</strong> — per-body camera target override that puts Cassini&#39;s POV alongside the ring-plane edge. <em>(per-flyby override hook)</em></li></ol><p>Items 1–4 land &quot;the post stack era&quot; of /fly. Items 5–7 land &quot;the cinematic shot-language era.&quot; Items 8–10 are the polish layer.</p><hr><h2 id="when-to-call-the-wave-done" tabindex="-1">When to call the wave done <a class="header-anchor" href="#when-to-call-the-wave-done" aria-label="Permalink to &quot;When to call the wave done&quot;">​</a></h2><p>A polish wave converges when 6 of the 8 checklist items pass at the hero moment of every flyby + arrival on every iconic mission. Use the Cassini Saturn-OI moment as the regression test: if it passes the silhouette test, three-layer test, limb-rim test, single-source-light test, negative-space test, and camera-disagree test, the wave is ready to ship.</p><p>Current Cassini hero shots pass:</p><ul><li>✓ Three-layer (with moons-on)</li><li>✓ Negative-space (mostly)</li><li>✓ Single-source-light (mostly — ambient still flattens)</li><li>✗ Silhouette (at 64×64 the ship reads only on Jupiter)</li><li>✗ Limb-rim (planets are centred + contained)</li><li>✗ Camera-disagree (ship and camera move together)</li></ul><p><strong>3/8 → 6/8 is the realistic next-wave target.</strong></p><hr><p><em>Cross-link:</em><a href="./fly-cinematic-shot-language">fly-cinematic-shot-language.md</a><a href="./../adr/TA">../adr/TA.md</a> — architecture map [/Users/markodragoljevic/.claude/projects/-Users-markodragoljevic-Projects-orrery/memory/project_fly_cinematic_vision.md](file:///Users/markodragoljevic/.claude/projects/-Users-markodragoljevic-Projects-orrery/memory/project_fly_cinematic_vision.md) — vision memory</p>',62)])])}const g=e(o,[["render",s]]);export{p as __pageData,g as default};
